const items = $input.all();

if (items.length === 0) {
  console.log('Keine Kandidaten gefunden!');
  return [];
}

// Nimm den ersten Kandidaten
const firstKandidat = items[0].json;

console.log('\n========== ALLE FELDER DES ERSTEN KANDIDATEN ==========\n');

// Alle Properties anzeigen
const allKeys = Object.keys(firstKandidat);
const properties = allKeys.filter(key => key.startsWith('property_'));

console.log('Gefundene Property-Felder:');
for (const prop of properties) {
  const value = firstKandidat[prop];
  console.log(`  ${prop}: ${JSON.stringify(value)}`);
}

console.log('\n========== SUCHE NACH DISTANZ-FELD ==========\n');

const distanzFelder = properties.filter(prop => 
  prop.toLowerCase().includes('distanz') || 
  prop.toLowerCase().includes('distance') ||
  prop.toLowerCase().includes('gewunschte') ||
  prop.toLowerCase().includes('km')
);

if (distanzFelder.length > 0) {
  console.log('✅ DISTANZ-FELDER GEFUNDEN:');
  for (const field of distanzFelder) {
    console.log(`  ${field}: ${firstKandidat[field]}`);
  }
} else {
  console.log('❌ KEIN DISTANZ-FELD GEFUNDEN!');
  console.log('Alle verfügbaren Felder:');
  console.log(properties.join(', '));
}

return [{
  json: {
    alle_felder: properties,
    distanz_felder: distanzFelder
  }
}];
